<?php

declare(strict_types=1);

namespace App\Play\Domain\Campaign\Characters;

/**
 * The campaign already holds a Character with this id. Ids are generated by the caller, so a
 * repeated command must not replace the existing Character.
 */
final class CharacterAlreadyExists extends \DomainException
{
    public static function withId(CharacterId $id): self
    {
        return new self(\sprintf('Character "%s" already exists.', $id->toString()));
    }
}
